  \"start\": \"node scripts/forge/start.mjs\",\n    \"forge:package\": \"node --max-old-space-size=8192 scripts/forge/run.mjs package\",\n    \"forge:make\": \"node --max-old-space-size=8192 scripts/forge/run.mjs make\",\n    \"package\": \"pnpm run harness:stage && pnpm run forge:package\",\n    \"make\": \"pnpm run harness:stage && pnpm run forge:make\",\n    \"make:macos\": \"pnpm run harness:stage && node scripts/forge/run.mjs make --platform=darwin\"\n  },\n  \"dependencies\": {\n    \"@lencx/minke-im-discord\": \"workspace:*\",\n    \"@lencx/minke-im-gateway\": \"workspace:*\",\n    \"@lencx/minke-im-telegram\": \"workspace:*\",\n    \"@lencx/minke-im-weixin\": \"workspace:*\",\n    \"@lencx/minke-model-runtime\": \"workspace:*\",\n    \"@lencx/minke-remote-access\": \"workspace:*\",\n    \"electron-squirrel-startup\": \"1.0.1\",\n    \"electron-window-state\": \"5.0.3\",\n    \"https-proxy-agent\": \"9.1.0\",\n    \"react\": \"19.2.8\",\n    \"react-dom\": \"19.2.8\",\n    \"ws\": \"8.21.3\"\n  },\n  \"devDependencies\": {\n    \"@deepseek-ai/dsh-client-shortcuts\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-settings-general\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-client-ui-sidebar-browser\": \"0.2.1-rc.2\",\n    \"@deepseek-ai/dsh-typert-protocol\": \"0.2.1-rc.2\",\n    \"@electron-forge/cli\": \"7.11.2\",\n    \"@electron-forge/core\": \"7.11.2\",\n    \"@electron-forge/maker-deb\": \"7.11.2\",\n    \"@electron-forge/maker-dmg\": \"7.11.2\",\n    \"@electron-forge/maker-rpm\": \"7.11.2\",\n    \"@electron-forge/maker-squirrel\": \"7.11.2\",\n    \"@electron-forge/maker-zip\": \"7.11.2\",\n    \"@electron-forge/plugin-fuses\": \"7.11.2\",\n    \"@electron-forge/plugin-vite\": \"7.11.2\",\n    \"@electron/fuses\": \"2.1.3\",\n    \"@electron/rebuild\": \"4.2.0\",\n    \"@tailwindcss/vite\": \"4.3.3\",\n    \"@types/electron-squirrel-startup\": \"1.0.2\",\n    \"@types/node\": \"26.2.0\",\n    \"@types/react\": \"19.2.18\",\n    \"@types/react-dom\":